import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"@jsprismarine/server","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"@jsprismarine/server"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/server/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/server/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/server/src"}},"headers":[],"relativePath":"api/@jsprismarine/server/index.md","filePath":"api/@jsprismarine/server/index.md","lastUpdated":1794414111000}`),a={name:`api/@jsprismarine/server/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../">API reference</a> / @jsprismarine/server</p><h1 id="jsprismarine-server" tabindex="-1">@jsprismarine/server <a class="header-anchor" href="#jsprismarine-server" aria-label="Permalink to “@jsprismarine/server”">​</a></h1><p><a href="https://discord.gg/kZZCDyCBbW" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/server" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/server" alt="npm"></a></p><p>The <code>prismarine</code> command line: argument parsing, the host process that runs the server as a child, the <code>--watch</code> file watcher, and the choice between the terminal UI and the plain line console.</p><p>Run <code>prismarine</code> in a terminal on Node 26.9 or newer (or 26.4 with <code>--experimental-ffi</code>) and it loads <code>@jsprismarine/console</code> and shows the UI. Anywhere else it runs the server in-process with the plain console, where each stdin line is a command and each log record is a stdout line. <code>--no-tui</code> or <code>JSP_NO_TUI=1</code> forces the plain console, <code>--headless</code> attaches no console at all, and <code>--watch</code> restarts the server when workspace source or loaded content pack data changes (<code>pnpm run dev</code> passes it). The flags and keys are documented in <a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/docs/guide/running.md#console" target="_blank" rel="noreferrer">Running JSPrismarine</a>.</p><h2 id="native-typescript-loader-prototype" tabindex="-1">Native TypeScript loader prototype <a class="header-anchor" href="#native-typescript-loader-prototype" aria-label="Permalink to “Native TypeScript loader prototype”">​</a></h2><p><code>pnpm --filter @jsprismarine/server run dev:native-prototype</code> runs the source entry with Node&#39;s built-in type stripping and a synchronous resolver for extensionless relative imports. The prototype currently stops at runtime TypeScript syntax that needs code generation, including <code>enum</code> declarations and parameter properties. The November 2026 source audit counted about 230 enums and 80 parameter properties; <a href="https://nodejs.org/api/typescript.html#typescript-features" target="_blank" rel="noreferrer">Node&#39;s TypeScript support</a> does not transform them. On Node 26.12.1, the native benchmark currently reaches <a href="./../worldgen/src/noise/NoiseStack.ts:24.html"><code>NoiseStack.ts:24</code></a> and fails on its <code>layers</code> parameter property before the import completes. Keep using <code>pnpm --filter @jsprismarine/server run dev</code> with <code>tsx</code> until the source graph is erasable or those files have a separate transform step.</p><p><code>pnpm --filter @jsprismarine/server run bench:native-typescript</code> compares elapsed time and process CPU while each loader imports the same server entry and handles <code>--help</code>. This checks module startup without starting a world or opening the server socket. The latest three-sample run measured TSX at 284 ms median elapsed and 387 ms median CPU; all native samples failed on the parameter property above (79 ms elapsed and 153 ms CPU median to failure). Those failure timings are not a successful startup comparison. <code>pnpm run typecheck</code> remains a separate required step because Node&#39;s type stripping does not type-check.</p>`,8)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};